@@ -18,6 +18,22 @@ test("no lessons", () => {
   expect(progressPercent([], [])).toBe(0);
 });

+test("never shows 100% before the last lesson", () => {
+  const lessons = Array.from({ length: 200 }, (_, i) => `l${i}`);
+  expect(progressPercent(lessons.slice(0, 199), lessons)).toBe(99);
+});
+
+test("shows 100% when every lesson is done", () => {
+  expect(progressPercent(["a", "b", "c"], ["a", "b", "c"])).toBe(100);
+});
+
+test("rounds down", () => {
+  expect(progressPercent(["a", "b"], ["a", "b", "c"])).toBe(66);
+});
+
+test("one lesson of three is 33%", () => {
+  expect(progressPercent(["a"], ["a", "b", "c"])).toBe(33);
+});
 test("half way", () => {
